--
-- Name: org_from_creator(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE OR REPLACE FUNCTION app.org_from_creator() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE memberships int;
BEGIN
  IF NEW.org_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.created_by IS NULL THEN
    RAISE EXCEPTION
      '%.% needs org_id, or a created_by whose organisation can be looked up',
      TG_TABLE_SCHEMA, TG_TABLE_NAME;
  END IF;

  -- A user with exactly one membership. Deliberately refuses to guess for
  -- somebody who belongs to two organisations: at that point the caller must
  -- say which one it is acting for.
  SELECT count(*) INTO memberships
    FROM platform.org_members m WHERE m.user_id = NEW.created_by;

  IF memberships = 1 THEN
    SELECT m.org_id INTO NEW.org_id
      FROM platform.org_members m WHERE m.user_id = NEW.created_by;
  END IF;

  IF NEW.org_id IS NULL THEN
    SELECT u.organization_id INTO NEW.org_id
      FROM public.users u WHERE u.id = NEW.created_by;
  END IF;

  IF NEW.org_id IS NULL THEN
    RAISE EXCEPTION 'cannot derive an organisation for created_by %', NEW.created_by;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: org_from_job(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE OR REPLACE FUNCTION app.org_from_job() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.org_id IS NOT NULL THEN RETURN NEW; END IF;

  SELECT r.org_id INTO NEW.org_id
    FROM core.requirements r WHERE r.id = NEW.job_id;

  IF NEW.org_id IS NULL AND NEW.candidate_id IS NOT NULL THEN
    SELECT p.org_id INTO NEW.org_id
      FROM core.people p WHERE p.id = NEW.candidate_id;
  END IF;

  IF NEW.org_id IS NULL THEN
    RAISE EXCEPTION
      'cannot derive an organisation for scoring_log: neither core.requirements % '
      'nor core.people % exists', NEW.job_id, NEW.candidate_id;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: processing_status(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE OR REPLACE FUNCTION app.processing_status(source_status text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE lower(coalesce(source_status, ''))
    WHEN 'processed'  THEN 'succeeded'
    WHEN 'failed'     THEN 'failed'
    WHEN 'processing' THEN 'running'
    ELSE 'pending'
  END
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE OR REPLACE FUNCTION app.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
  BEGIN
    NEW.updated_at := now();
    RETURN NEW;
  END
  $$;


