    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT applications_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'alpha'::text, 'beta'::text, 'available'::text, 'retired'::text])))
);


--
-- Name: features; Type: TABLE; Schema: platform; Owner: -
