);


--
-- Name: review_queue; Type: TABLE; Schema: syntra; Owner: -
--

CREATE TABLE syntra.review_queue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid,
    organization_id uuid,
    action_type text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    title text NOT NULL,
    message text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    source_event_type text,
    source_event_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    decided_by uuid,
    decision_note text,
    CONSTRAINT recruiter_review_items_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'dismissed'::text])))
);


--
-- Name: recruiter_review_items; Type: VIEW; Schema: syntra; Owner: -
--

CREATE VIEW syntra.recruiter_review_items WITH (security_invoker='true') AS
 SELECT id,
    user_id,
    organization_id,
    action_type,
    status,
    title,
    message,
    payload,
    source_event_type,
    source_event_id,
    created_at,
    decided_at,
    decided_by,
    decision_note
   FROM syntra.review_queue;


--
-- Name: scoring_log; Type: TABLE; Schema: syntra; Owner: -
--

CREATE TABLE syntra.scoring_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    resume_id uuid NOT NULL,
    candidate_id uuid,
    model_name text,
    model_version text,
    score numeric(5,2),
    tier text,
    features jsonb DEFAULT '{}'::jsonb NOT NULL,
    top_features jsonb,
    used_fallback boolean DEFAULT false NOT NULL,
    fallback_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    org_id uuid NOT NULL
);


